import{_t as e,it as t,n,rt as r}from"./chunks/framework.CJEq1BAB.js";var i=JSON.parse(`{"title":"Setup","description":"","frontmatter":{"title":"Setup"},"headers":[],"relativePath":"de/api/reference/setup.md","filePath":"de/api/reference/setup.md"}`),a={name:`de/api/reference/setup.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="setup" tabindex="-1">Setup <a class="header-anchor" href="#setup" aria-label="Permalink to “Setup”">​</a></h1><div><p>Operationen des Tags <strong>Setup</strong>, die dieses Release implementiert. Erzeugt aus <code>api/openapi.yaml</code>; geplante Operationen sind nicht aufgeführt. Die Beschreibungen stammen aus dem englischen API-Vertrag.</p><h2 id="getSetupStatus" tabindex="-1">Whether the instance still needs its local bootstrapping (US-013) <a class="header-anchor" href="#getSetupStatus" aria-label="Permalink to “Whether the instance still needs its local bootstrapping (US-013)”">​</a></h2><p><code>GET /setup/status</code> · <code>getSetupStatus</code></p><p>Public, because no principal exists before the bootstrapping. Returns only whether setup is required – no token, account or instance data.</p><p><strong>Zugriff</strong>: öffentlich – ohne Anmeldung</p><h3 id="antworten" tabindex="-1">Antworten <a class="header-anchor" href="#antworten" aria-label="Permalink to “Antworten”">​</a></h3><table tabindex="0"><thead><tr><th>Status</th><th>Beschreibung</th><th>Problem-Typen</th></tr></thead><tbody><tr><td>200</td><td>Setup status</td><td>–</td></tr><tr><td>429</td><td>Rate or concurrency limit exceeded (REQ-186)</td><td>–</td></tr></tbody></table><h2 id="completeSetup" tabindex="-1">Local bootstrapping – create the system admin account and the instance slug (US-013) <a class="header-anchor" href="#completeSetup" aria-label="Permalink to “Local bootstrapping – create the system admin account and the instance slug (US-013)”">​</a></h2><p><code>POST /setup</code> · <code>completeSetup</code></p><p>Public, but only effective with the one-time setup token, which the backend writes to a file inside its container and never returns or logs (REQ-017, REQ-175). Exactly one bootstrapping can succeed per instance (REQ-015); every attempt is audited as <code>system.bootstrapped</code> or <code>system.bootstrap-rejected</code> (REQ-016). The request body is never logged.</p><p><strong>Zugriff</strong>: öffentlich – ohne Anmeldung</p><h3 id="request-body" tabindex="-1">Request-Body <a class="header-anchor" href="#request-body" aria-label="Permalink to “Request-Body”">​</a></h3><ul><li><code>application/json</code>: SetupRequest</li></ul><h3 id="antworten-1" tabindex="-1">Antworten <a class="header-anchor" href="#antworten-1" aria-label="Permalink to “Antworten”">​</a></h3><table tabindex="0"><thead><tr><th>Status</th><th>Beschreibung</th><th>Problem-Typen</th></tr></thead><tbody><tr><td>201</td><td>System admin account created; the instance is bootstrapped</td><td>–</td></tr><tr><td>400</td><td>Invalid input (problem type <code>urn:oea:problem:validation-failed</code>); <code>invalidFields</code> names the rejected fields. Only checked after a valid setup token.</td><td><code>urn:oea:problem:validation-failed</code></td></tr><tr><td>401</td><td>Setup token missing, wrong or expired (problem type <code>urn:oea:problem:invalid-setup-token</code>)</td><td><code>urn:oea:problem:invalid-setup-token</code></td></tr><tr><td>409</td><td>The instance is already bootstrapped (problem type <code>urn:oea:problem:already-bootstrapped</code>)</td><td><code>urn:oea:problem:already-bootstrapped</code></td></tr><tr><td>413</td><td>Request body larger than the configured limit (problem type <code>urn:oea:problem:request-too-large</code>, REQ-186); nothing is processed. The limits are configurable by the operator – 1 MB by default, 10 MB for the entity batch.</td><td><code>urn:oea:problem:request-too-large</code></td></tr><tr><td>429</td><td>Rate or concurrency limit exceeded (REQ-186)</td><td>–</td></tr></tbody></table></div>`,2)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};